import { expect, test, type Page } from "@playwright/test";
import { login } from "./hub-auth";

async function waitLive(page: Page) {
  await expect(page.getByTestId("journal-banner")).toHaveCount(0, { timeout: 20_000 });
}

test.describe.configure({ mode: "serial" });

const created: string[] = [];
test.afterAll(async ({ browser }) => {
  const page = await browser.newPage();
  try {
    await login(page, "e2e-offline-outbox");
    for (const id of created) {
      await page.request.delete(`/v1/instances/${id}?force=1`);
    }
  } finally {
    await page.close();
  }
});

async function makeSession(page: Page, seed: string): Promise<string> {
  await page.goto("/sessions/new");
  const hostPicker = page.getByTestId("new-session-host");
  await expect(hostPicker).toContainText("e2e-fake-node", { timeout: 20_000 });
  const hostId = await hostPicker.locator("option").filter({ hasText: "e2e-fake-node" }).getAttribute("value");
  expect(hostId).toBeTruthy();
  await hostPicker.selectOption(hostId!);
  await page.getByTestId("new-session-kind-claude").click();
  await expect(page.getByTestId("new-session-workspace").locator("option")).not.toHaveCount(0, { timeout: 20_000 });
  await page.getByTestId("new-session-prompt").fill(seed);
  await page.getByTestId("new-session-start").click();
  await page.waitForURL(/\/s\//);
  const id = new URL(page.url()).pathname.split("/")!.pop()!;
  created.push(id);
  await expect(page.getByTestId("session-page")).toBeVisible({ timeout: 30_000 });
  return id;
}

test("bisect A: setOffline cycle, no reload, no SW — follow recovers", async ({ page }) => {
  await login(page);
  await makeSession(page, "bisect A seed");
  const events: string[] = [];
  const t0 = Date.now();
  page.on("websocket", (w) => {
    events.push(`+${((Date.now() - t0) / 1000).toFixed(1)} open`);
    w.on("framereceived", () => events.push(`+${((Date.now() - t0) / 1000).toFixed(1)} frame`));
    w.on("close", () => events.push(`+${((Date.now() - t0) / 1000).toFixed(1)} close`));
  });
  await waitLive(page);
  await page.context().setOffline(true);
  await expect(page.getByTestId("journal-banner")).toHaveAttribute("data-state", "offline");
  await page.waitForTimeout(3_000);
  await page.context().setOffline(false);
  await page.waitForTimeout(20_000);
  console.log("BISECT_A_EVENTS\n" + events.join("\n"));
  await waitLive(page);
});

test("bisect B: SW + offline reload — follow recovers", async ({ page }) => {
  await login(page);
  await makeSession(page, "bisect B seed");

  const SW = `self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (e) => e.waitUntil(self.clients.claim()));
self.addEventListener("fetch", (event) => {
  const u = new URL(event.request.url);
  if (u.pathname.startsWith("/v1/")) return;
  event.respondWith(fetch(event.request).catch(() => Response.error()));
});`;
  await page.context().route("**/e2e-bisect-sw.js", (r) =>
    r.fulfill({ contentType: "application/javascript; charset=utf-8", body: SW }),
  );
  await page.evaluate(async () => {
    await navigator.serviceWorker.register("/e2e-bisect-sw.js");
    await navigator.serviceWorker.ready;
  });
  await page.goto(page.url());
  await waitLive(page);

  const events: string[] = [];
  const t0 = Date.now();
  page.on("websocket", (w) => {
    events.push(`+${((Date.now() - t0) / 1000).toFixed(1)} open`);
    w.on("framereceived", () => events.push(`+${((Date.now() - t0) / 1000).toFixed(1)} frame`));
    w.on("close", () => events.push(`+${((Date.now() - t0) / 1000).toFixed(1)} close`));
  });

  await expect(page.getByTestId("session-page")).toBeVisible();
  await expect(page.getByTestId("journal-banner")).toHaveCount(0, { timeout: 20_000 });
  await page.context().setOffline(true);
  await expect(page.getByTestId("journal-banner")).toHaveAttribute("data-state", "offline", { timeout: 20_000 });
  await page.waitForTimeout(2_000);
  await page.reload({ waitUntil: "domcontentloaded" });
  await expect(page.getByTestId("session-page")).toBeVisible({ timeout: 20_000 });
  await expect(page.getByTestId("journal-banner")).toBeVisible({ timeout: 20_000 });
  await page.context().setOffline(false);
  await page.waitForTimeout(25_000);
  console.log("BISECT_B_EVENTS\n" + events.join("\n"));
  await waitLive(page);
});
